private void refreshCache(){
  int maxCachedInstalledRank=cache.isEmpty() ? -1 : cache.getLast().getInstalledRank();
  String query=database.getSelectStatement(table);
  try {
    cache.addAll(jdbcTemplate.query(query,rs -> {
